 "content": "from collections import Counter, deque


def transform(grid):
    """Fill enclosed background holes: odd area with 7, even area with 2."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            reaches_border = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if y in (0, h - 1) or x in (0, w - 1):
                    reaches_border = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w
                            and grid[ny][nx] == background
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not reaches_border:
                fill = 7 if len(cells) % 2 else 2
                for y, x in cells:
                    out[y][x] = fill
    return out


